SELECT id, symbol, side, status, quantity, entry_price, stop_loss, take_profit, exit_price, realized_pnl, close_reason, signal_id, exit_signal_id, opened_at, closed_at, TIMESTAMPDIFF(SECOND, opened_at, closed_at) AS hold_s, LEFT(entry_reason, 600) AS entry_reason_600, LEFT(exit_reason, 600) AS exit_reason_600 FROM crypto_ai.paper_position WHERE id IN (182,172,162,158,143,137) ORDER BY closed_at DESC;